  var b2=el('button','btn', w2.up? '✂️ '+T('Cut ISP 2 cable','ISP 2 ka cable kaato') : '🔌 '+T('Repair ISP 2','ISP 2 theek karo')); b2.type='button'; b2.style.minHeight='52px';
  if(w2.up) b2.style.background='#dc2626'; b2.style.color='#fff';
